#!/usr/bin/env node
// Regenerate src/assets/leafletBundle.ts after upgrading leaflet in node_modules.
// Usage: node scripts/bundleLeaflet.js
const fs = require('fs');
const path = require('path');

const distDir = path.join(__dirname, '..', 'node_modules', 'leaflet', 'dist');
const js = fs.readFileSync(path.join(distDir, 'leaflet.js'), 'utf8');
const css = fs.readFileSync(path.join(distDir, 'leaflet.css'), 'utf8');

const out = [
  '// Auto-generated by scripts/bundleLeaflet.js — do not edit manually',
  '// Re-run after upgrading leaflet in node_modules',
  `export const LEAFLET_JS: string = ${JSON.stringify(js)};`,
  `export const LEAFLET_CSS: string = ${JSON.stringify(css)};`,
  '',
].join('\n');

const outPath = path.join(__dirname, '..', 'src', 'assets', 'leafletBundle.ts');
fs.writeFileSync(outPath, out, 'utf8');
console.log('Wrote', outPath, '(' + out.length + ' chars)');
